package quarry.analysis

/**
 * Unicode 12.1 character properties used by the tokenizer, loaded from the
 * table generated by scripts/gen_unicode.py. Lucene's StandardTokenizer
 * grammar is generated from Unicode 12.1 too, so both agree on every
 * character, including ones newer Unicode versions have reclassified.
 */
internal object Unicode12 {
    // Word_Break values (the low five bits of the class byte).
    const val OTHER = 0
    const val ALETTER = 1
    const val HEBREW = 2
    const val NUMERIC = 3
    const val KATAKANA = 4
    const val EXTEND_NUM_LET = 5
    const val MID_LETTER = 6
    const val MID_NUM = 7
    const val MID_NUM_LET = 8
    const val SINGLE_QUOTE = 9
    const val DOUBLE_QUOTE = 10
    const val EXTEND = 11
    const val FORMAT = 12
    const val ZWJ = 13
    const val REGIONAL_INDICATOR = 14

    // Flags in the class byte.
    const val SOUTHEAST_ASIAN = 0x20 // Line_Break = Complex_Context
    const val HAN = 0x40
    const val HIRAGANA = 0x80

    // Emoji property bits.
    const val EMOJI = 1
    const val EMOJI_MODIFIER = 4
    const val EMOJI_MODIFIER_BASE = 8
    const val EXTENDED_PICTOGRAPHIC = 16

    private const val DIRECT = 0x30000 // code points below this use flat tables
    private val cls = ByteArray(DIRECT)
    private val emo = ByteArray(DIRECT)
    private val highStart: IntArray
    private val highEnd: IntArray
    private val highCls: ByteArray
    private val highEmo: ByteArray

    init {
        val stream = Unicode12::class.java.getResourceAsStream("/quarry/unicode12.dat")
            ?: error("missing resource /quarry/unicode12.dat")
        val hs = ArrayList<Int>()
        val he = ArrayList<Int>()
        val hc = ArrayList<Byte>()
        val hm = ArrayList<Byte>()
        stream.bufferedReader().useLines { lines ->
            for (line in lines) {
                if (line.startsWith("#") || line.isBlank()) continue
                val p = line.split(' ')
                val lo = p[0].toInt(16)
                val hi = p[1].toInt(16)
                val c = p[2].toInt(16).toByte()
                val e = p[3].toInt(16).toByte()
                if (hi < DIRECT) {
                    cls.fill(c, lo, hi + 1)
                    emo.fill(e, lo, hi + 1)
                } else {
                    if (lo < DIRECT) {
                        cls.fill(c, lo, DIRECT)
                        emo.fill(e, lo, DIRECT)
                    }
                    hs += maxOf(lo, DIRECT); he += hi; hc += c; hm += e
                }
            }
        }
        highStart = hs.toIntArray()
        highEnd = he.toIntArray()
        highCls = hc.toByteArray()
        highEmo = hm.toByteArray()
    }

    private fun high(cp: Int, table: ByteArray): Int {
        var lo = 0
        var hi = highStart.size - 1
        while (lo <= hi) {
            val mid = (lo + hi) ushr 1
            when {
                highEnd[mid] < cp -> lo = mid + 1
                highStart[mid] > cp -> hi = mid - 1
                else -> return table[mid].toInt() and 0xFF
            }
        }
        return 0
    }

    /** Word_Break value plus the SA/Han/Hiragana flags. */
    fun classOf(cp: Int): Int = if (cp < DIRECT) cls[cp].toInt() and 0xFF else high(cp, highCls)

    fun wordBreak(cp: Int): Int = classOf(cp) and 0x1F

    fun emojiOf(cp: Int): Int = if (cp < DIRECT) emo[cp].toInt() and 0xFF else high(cp, highEmo)
}
